impl Solution {
    pub fn count_monobit(n: i32) -> i32 {
        let mut count = 0;
        for i in 0..=n {
            if is_monobit(i) {
                count += 1;
            }
        }
        count
    }

    fn is_monobit(n: i32) -> bool {
        if n == 0 {
            return true;
        }

        let mut temp = n;
        let mut first_bit = (temp & 1) as i32;

        while temp > 0 {
            let current_bit = (temp & 1) as i32;
            if current_bit != first_bit {
                return false;
            }
            temp >>= 1;
        }

        true
    }
}

